#!/usr/bin/env python3
"""PDF breve para compartir con estudiantes que ejecutan Garritas en Windows."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Preformatted, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'docs/manuales'
for n,f in [('GS','DejaVuSans.ttf'),('GSBold','DejaVuSans-Bold.ttf'),('GSMono','DejaVuSansMono.ttf')]:
 pdfmetrics.registerFont(TTFont(n,'/usr/share/fonts/truetype/dejavu/'+f))
pdfmetrics.registerFontFamily('GS',normal='GS',bold='GSBold',italic='GS',boldItalic='GSBold')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='BodyGS',fontName='GS',fontSize=10,leading=15,spaceAfter=9))
s.add(ParagraphStyle(name='CodeGS',fontName='GSMono',fontSize=8,leading=12,spaceBefore=4,spaceAfter=11))
s.add(ParagraphStyle(name='SmallGS',fontName='GS',fontSize=8,leading=12,spaceAfter=7))
s.add(ParagraphStyle(name='TitleGS',fontName='GSBold',fontSize=23,leading=29,textColor=colors.HexColor('#245b47'),spaceAfter=15))
s.add(ParagraphStyle(name='HGS',fontName='GSBold',fontSize=15,leading=21,textColor=colors.HexColor('#245b47'),spaceBefore=9,spaceAfter=10))
flow=[];md=[];all_commands=[]
def p(t,small=False):
 flow.append(Paragraph(t,s['SmallGS' if small else 'BodyGS']));md.append(t.replace('<b>','**').replace('</b>','**')+'\n')
def h(t):flow.append(Paragraph(escape(t),s['HGS']));md.append('\n## '+t+'\n')
def code(t):
 for line in t.splitlines():
  assert pdfmetrics.stringWidth(line,'GSMono',8)<=A4[0]-96,repr(line)
 flow.append(Preformatted(t,s['CodeGS']));md.append('```powershell\n'+t+'\n```\n');all_commands.append(t)
def page():flow.append(PageBreak())
def table(headers,rows,widths):
 content=[[Paragraph(escape(c),s['SmallGS']) for c in row] for row in [headers,*rows]]
 t=Table(content,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#deebe1')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#cedbd2')),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));flow.append(t);flow.append(Spacer(1,10))
 md.append('| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+'\n'.join('| '+' | '.join(row)+' |' for row in rows)+'\n')
def footer(c,d):
 c.setFont('GS',8);c.setFillColor(colors.HexColor('#52685a'));c.drawString(48,26,'Garritas Store · Guía Windows para compartir');c.drawRightString(A4[0]-48,26,str(d.page))
flow.append(Paragraph('Garritas Store\nGuía rápida para Windows',s['TitleGS']))
p('Desde la clonación hasta abrir la tienda. Comandos seleccionables y copiables para PowerShell. <b>Edición: 28 de octubre de 2026, Perú.</b>')
p('Copia únicamente el contenido de cada bloque, sin el prefijo PS C:\\...&gt;. Ejecuta los pasos en orden y espera a que termine cada uno. No pegues todos los bloques juntos: algunos son alternativas o soluciones para errores.')
h('1. Antes de clonar')
p('Instala Git, <b>JDK 21 completo</b>, <b>Node.js 24</b> y Docker Desktop con contenedores Linux. Abre Docker Desktop y espera a que su motor arranque. En una PowerShell nueva comprueba:')
code('git --version\njava -version\njavac -version\nnode --version\nnpm.cmd --version\ndocker compose version\ndocker info')
p('Java y javac deben indicar 21; Node debe indicar v24.x.x. Docker info debe mostrar la sección <b>Server</b> sin errores. Cero contenedores o imágenes es normal antes del primer arranque.')
p('Si un comando no se reconoce, instala esa herramienta o corrige PATH; cierra y vuelve a abrir PowerShell después de instalar. En la página 7 están los enlaces oficiales y los problemas habituales.')
h('Qué modalidad usarás')
p('Windows ejecuta los servicios Java y Angular. Docker ejecuta las bases, Kafka, Keycloak y monitorización. El lanzador automatiza el orden; <b>no necesitas iniciar los ocho microservicios por separado</b>. Cada compañera ejecuta su propia copia local.')
page()
h('2. Clonar la rama correcta')
p('Abre PowerShell normal. Este bloque guarda la copia en C:\\Users\\TU_USUARIO\\proyectos\\Garritas-. La variable $HOME se adapta a cada computadora.')
code('cd $HOME\nNew-Item -ItemType Directory -Force proyectos\ncd proyectos\ngit clone --branch feat/garritas-store https://github.com/Nikol235/Garritas-.git\ncd Garritas-\ngit branch --show-current')
p('La última salida debe ser <b>feat/garritas-store</b>. Si Garritas- ya existe, no borres nada ni vuelvas a clonar encima: entra en tu copia y revisa su estado. Para actualizar una copia ya clonada, consulta la página 6.')
h('3. Permitir el script en esta ventana')
p('Desde la carpeta del proyecto ejecuta:')
code('Set-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force')
p('El cambio dura únicamente durante esta sesión de PowerShell. Si abres otra ventana para ejecutar el lanzador, repite este comando allí. No cambia permanentemente la política del equipo.')
h('4. Compilar e instalar dependencias')
code('.\\uso-rapido\\garritas.ps1 -Accion build')
p('Descarga las dependencias Maven, compila los módulos Java e instala y compila Angular. Puede tardar varios minutos la primera vez; conserva Internet y espera.')
p('Si Angular pregunta <b>Would you like to share pseudonymous usage data… (y/N)</b>, escribe <b>N</b> y presiona Enter. Es una pregunta de estadísticas, no un error.')
p('Al terminar Java debe indicar BUILD SUCCESS y Angular debe completar su build. El prompt PS C:\\...&gt; vuelve cuando termina todo el comando. Si aparece BUILD FAILURE, Error o Falló un comando, guarda el mensaje y corrige antes de continuar.')
page()
h('5. Arrancar todo')
p('Deja Docker Desktop abierto. En la misma PowerShell, dentro de Garritas-, ejecuta:')
code('.\\uso-rapido\\garritas.ps1 -Accion iniciar')
p('<b>Importante: pueden abrirse varias ventanas de CMD/consola.</b> Es el lanzador iniciando procesos Java y Angular mediante Start-Process. No las cierres durante el uso: podrías detener aplicaciones.')
p('Este paso descarga imágenes si faltan, levanta contenedores y espera los servicios. No ejecutes iniciar dos veces ni vuelvas a ejecutar build mientras este arranque sigue trabajando.')
table(['Orden','Componentes'],[('1','Kafka, Kafka UI y Keycloak con su base'),('2','Ocho bases PostgreSQL de negocio'),('3','Config Server y Eureka'),('4','Catálogo, Institución, Usuario, Bienestar, Venta, Pago, Citas y Envío'),('5','API Gateway y Angular')],[55,444])
h('6. Si la terminal no te deja escribir')
p('Si todavía no aparece el prompt, el comando ocupa esa terminal. <b>No cierres las consolas ni repitas el arranque.</b> Presiona Windows + R, escribe powershell y pulsa Enter para abrir una ventana nueva.')
p('En la nueva ventana pega:')
code('cd "$HOME\\proyectos\\Garritas-"\nSet-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force\n.\\uso-rapido\\garritas.ps1 -Accion estado')
p('El estado debe ir mostrando OK. Si el arranque aún está en curso, algunos pueden aparecer FALLO: espera a que termine y vuelve a consultar estado. Si el arranque original terminó con error, revisa sus últimas líneas y los logs; no supongas que está todo listo por ver consolas abiertas.')
page()
h('7. Abrir la tienda y las consolas')
p('Abre las direcciones en el navegador <b>de la computadora donde ejecutaste Garritas</b>. localhost no es una dirección para acceder a la computadora de otra compañera.')
table(['Aplicación','Dirección local'],[('Garritas Store','http://localhost:4200'),('Kafka UI','http://localhost:18085'),('Keycloak: administración','http://localhost:18180/admin/'),('Eureka: servicios registrados','http://localhost:18761'),('Gateway: API','http://localhost:18080/api/v1/productos')],[175,324])
h('Cuentas de demostración')
table(['Uso','Usuario','Contraseña'],[('Cliente de tienda','cliente','Cliente123!'),('Administrador de tienda','admin-store','Admin123!'),('Administrador Keycloak','admin','local-admin-change-me'),('Grafana, si lo arrancas','admin','local-grafana')],[168,130,201])
p('El administrador de Keycloak es distinto del administrador de la tienda. Estas cuentas son de laboratorio: no las uses para exponer el sistema en Internet.')
h('8. Primer recorrido para comprobar funcionamiento')
for text in ['Entra como cliente. Consulta Sedes y selecciona una sede activa.','En Nueva orden añade productos; revisa cantidades y el carrito.','Elige YAPE o PLIN para aprobación simulada. Confirma y espera a que Mis pedidos muestre Pagada. TRANSFERENCIA simula rechazo y compensación de stock.','Completa Mi cuenta y registra una mascota antes de reservar una cita. Usa fecha futura en intervalos de 30 minutos.','Solicita envío para un pedido pagado. Como ADMIN puedes confirmar/atender citas y marcar tránsito/entrega.','Como cliente no debes poder editar sedes; como ADMIN sí. Los datos de cada cliente se controlan también en la API.']:
 p('• '+text)
p('Los pagos son simulados: no se realiza un cobro bancario real.',small=True)
page()
h('9. Monitorización opcional')
p('Cuando la tienda y los servicios estén listos, desde la raíz del proyecto ejecuta:')
code('docker compose -f obs/compose-dev.yml up -d')
p('Espera un momento y abre:')
table(['Herramienta','Dirección','Uso'],[('Grafana','http://localhost:13000','Paneles y consultas; admin / local-grafana'),('Prometheus','http://localhost:19090','Targets y métricas'),('Loki','http://localhost:13100/ready','Estado de su API; los logs se consultan en Grafana')],[90,210,199])
p('No uses obs/compose.yml para estos puertos: ese archivo es de otra modalidad. Kafka UI ya se inicia con el lanzador principal; no necesita este paso opcional.')
h('Puertos de los servicios de negocio')
table(['Microservicio','HTTP','PostgreSQL host'],[('Venta','8081','15441'),('Institución / sedes','8082','15442'),('Envío','8083','15443'),('Citas','8084','15444'),('Catálogo','8085','15445'),('Usuario / mascotas','8086','15446'),('Pago','8087','15447'),('Bienestar / especialistas','8088','15448')],[239,95,165])
p('Infraestructura: Config Server 18888; Eureka 18761; Gateway 18080. Kafka usa 19092 desde el host (no es una página web). Las bases usan 5432 dentro de sus contenedores, publicados como 15441–15448 en Windows. Angular utiliza Gateway; no tienes que abrir manualmente cada puerto de negocio.')
page()
h('10. Detener y volver a iniciar')
p('Para detener Java y Angular de forma gestionada, desde una PowerShell en el proyecto:')
code('.\\uso-rapido\\garritas.ps1 -Accion detener')
p('Los contenedores y volúmenes se conservan. Para volver a usar la misma versión, abre Docker Desktop y ejecuta:')
code('cd "$HOME\\proyectos\\Garritas-"\nSet-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force\n.\\uso-rapido\\garritas.ps1 -Accion iniciar')
p('Si el comando iniciar todavía está ejecutándose y deseas cancelarlo, usa Ctrl+C en la terminal original, espera el prompt y después ejecuta detener. No borres .runtime/windows-processes.json para forzar otro arranque: primero comprueba y detén los procesos registrados.')
h('11. Actualizar una copia que ya existe')
p('Solo cuando hayas detenido Java y Angular. Revisa git status: si muestra trabajo propio, consérvalo antes de actualizar; no uses reset --hard para saltarte esa revisión.')
code('cd "$HOME\\proyectos\\Garritas-"\ngit status\ngit branch --show-current')
p('Si estás en feat/garritas-store y no tienes cambios locales pendientes:')
code('git pull --ff-only origin feat/garritas-store\nSet-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force\n.\\uso-rapido\\garritas.ps1 -Accion build\n.\\uso-rapido\\garritas.ps1 -Accion iniciar')
p('Ejecuta los comandos uno a uno. Si pull o build falla, detente antes de iniciar. Normalmente no necesitas compilar en cada sesión: vuelve a compilar cuando actualices o cambies código.')
h('Datos y limpieza')
p('No ejecutes docker compose down -v como limpieza rutinaria: puede eliminar los volúmenes con datos. Para detener el laboratorio puedes usar detener y luego cerrar Docker Desktop; los volúmenes no son una copia de seguridad.')
page()
h('12. Problemas frecuentes y comandos de diagnóstico')
p('<b>Docker Desktop is unable to start.</b> Primero prueba WSL:')
code('wsl --status\nwsl --list --verbose\nwsl -d Ubuntu -- uname -r')
p('El último comando solo aplica si tienes una distribución llamada Ubuntu. Para reiniciar WSL guarda tu trabajo, cierra Docker Desktop completamente, ejecuta el siguiente comando, vuelve a abrir Docker Desktop y comprueba docker info:')
code('wsl --shutdown\n# Ahora abre Docker Desktop desde Inicio; espera y ejecuta:\ndocker info')
p('<b>No abre la tienda / FALLO en un servicio.</b> Usa estado y consulta el log concreto. Ejemplo de Catálogo (sustituye el nombre por el servicio que falló):')
code('Get-Content .runtime\\garritas-catalogo-ms\\error.log -Tail 60\nGet-Content .runtime\\garritas-catalogo-ms\\console.log -Tail 60')
p('Angular escribe .runtime/frontend.log y frontend-error.log. Para contenedores:')
code('docker ps -a\ndocker compose -f kafka/compose-dev.yml logs --tail 60\ndocker compose -f keycloak/compose-dev.yml logs --tail 60')
p('<b>Ya existe un arranque registrado.</b> Ejecuta estado. Si necesitas reiniciar, termina/cancela el arranque original y utiliza detener antes de iniciar de nuevo. No lances procesos duplicados.')
p('<b>Avisos npm o pregunta de Angular.</b> Responde N a estadísticas. npm fund y los avisos de actualización no son por sí mismos fallos del build. Si hay vulnerabilidades, registra y revisa npm audit antes de publicar; no ejecutes npm audit fix --force a ciegas.')
h('Instaladores oficiales si faltan herramientas')
p('Git: https://git-scm.com/downloads/win<br/>JDK 21: https://adoptium.net/temurin/releases/?version=21<br/>Node.js: https://nodejs.org/en/download (elige versión 24)<br/>Docker Desktop: https://www.docker.com/products/docker-desktop/',small=True)
p('Si necesitas ayuda, comparte el comando que ejecutaste y el error completo. El código se validó en DEV Linux; esta guía recoge el flujo PowerShell y los problemas observados durante el arranque en Windows. No acredita todas las configuraciones posibles de Windows.',small=True)

pdf=OUT/'04-Guia-rapida-Windows-companeras.pdf'
SimpleDocTemplate(str(pdf),pagesize=A4,leftMargin=48,rightMargin=48,topMargin=40,bottomMargin=43,title='Garritas Store: guía rápida Windows con comandos copiables',author='Garritas Store').build(flow,onFirstPage=footer,onLaterPages=footer)
(SOURCE:=OUT/'fuentes').joinpath('04-Guia-rapida-Windows-companeras.md').write_text('\n'.join(md))
# Texto de apoyo: no es un script ejecutable; las alternativas no se corren en bloque.
(OUT/'04-Comandos-Windows-copiables.txt').write_text('GARRITAS STORE - COMANDOS PARA POWERSHELL\n\nEjecuta por etapas; no pegues este archivo completo. Lee el PDF para requisitos, preguntas y errores.\n\n'+'\n\n'.join(str(i+1)+'. '+label+'\n'+command for i,(label,command) in enumerate(zip(['Comprobar requisitos','Clonar por primera vez','Permitir script en esta ventana','Compilar (esperar hasta el final)','Iniciar (Docker Desktop abierto)','Consultar estado en una ventana nueva','Monitorizacion opcional','Detener Java y Angular','Volver a iniciar otra sesion','Revisar antes de actualizar','Actualizar solo sin cambios locales; ejecutar uno por uno','Diagnostico WSL; Ubuntu debe existir','Reiniciar WSL solo si Docker no arranca','Leer logs de Catalogo si falla','Leer estado/logs de contenedores'],all_commands)))+'\n')
print(pdf)
